---@class UIBattlePlayerInfoMgr
local UIBattlePlayerInfoMgr = {}

------------ Init ------------
function UIBattlePlayerInfoMgr:Init()
    self:CleanField()
end

function UIBattlePlayerInfoMgr:Delete()
    self:CleanField()
end

function UIBattlePlayerInfoMgr:CleanField()
    self.playerDesc = nil
    self.myPlayerId = nil   -- 这里保存的是主控端的playerId，因为有观战的情况，所以不一定是我自己的playerId（不一定是playerComponent里面的id）

    self.defaultPlayerDesc = nil
    self.defaultEnemyDesc = nil
end

--- func desc
---@param initData table {"playerDesc" : { "1" /*玩家playerId*/ : { "name" :"玩家名", "avatar" :"玩家头像id", "avatarFrame" :"玩家头像框id"}}
---@param myPlayerId integer 主控端的playerId
function UIBattlePlayerInfoMgr:InitPlayerInfo(initData, myPlayerId)
    self.playerDesc = initData.campDesc
    -- 如果外面没传就用本地的id
    if myPlayerId == nil then
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        self.myPlayerId = playerComponent.playerDojo.playerId
    else
        self.myPlayerId = myPlayerId
    end
    self:MakeDefaultDesc(initData.questId)
end

------------ Init ------------

function UIBattlePlayerInfoMgr:MakeDefaultDesc(questId)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local idAIHead
    local aiName
    if not isNull(questId) then
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
        idAIHead = questVo and questVo.aiHead or 0
        aiName = questVo and questVo.aiName or ""
    end
    self.defaultPlayerDesc = {
        name = playerComponent.playerDojo.playerName,
        avatar = playerComponent.playerDojo.playerAvatar,
        avatarFrame = playerComponent.playerDojo.playerAvatarFrame,
    }
    self.defaultEnemyDesc = {
        name = checkString(aiName),
        avatar = checkInt(idAIHead),
        avatarFrame = nil,
    }
end

function UIBattlePlayerInfoMgr:GetPlayerDescById(playerId)
    if isNull(self.playerDesc) then
        return self.defaultPlayerDesc
    end
    local myPlayerDesc = self.playerDesc[playerId]
    if isNull(myPlayerDesc) then
        return self.defaultPlayerDesc
    end
    return myPlayerDesc
end

--- 获取主控的playerName
function UIBattlePlayerInfoMgr:GetMyPlayerName()
    if isNull(self.playerDesc) then
        return self.defaultPlayerDesc.name
    end
    local myPlayerDesc = self.playerDesc[self.myPlayerId]
    if isNull(myPlayerDesc) then
        return self.defaultPlayerDesc.name
    end
    return myPlayerDesc.name
end

--- 获取另一方的玩家名称
function UIBattlePlayerInfoMgr:GetOtherPlayerName()
    return self:GetOtherPlayerDesc().name
end

--- 获取另一方的玩家id
function UIBattlePlayerInfoMgr:GetOtherPlayerId()
    if isNull(self.playerDesc) then
        return -1
    end
    for playerId, desc in pairs(self.playerDesc) do
        if playerId ~= self.myPlayerId then
            return playerId
        end
    end
    return -1
end

--- 获取主控的playerDesc
function UIBattlePlayerInfoMgr:GetMyPlayerDesc()
    if isNull(self.playerDesc) then
        return self.defaultPlayerDesc
    end
    local myPlayerDesc = self.playerDesc[self.myPlayerId]
    if isNull(myPlayerDesc) then
        return self.defaultPlayerDesc
    end
    return myPlayerDesc
end

--- 获取另外一方的playerDesc
function UIBattlePlayerInfoMgr:GetOtherPlayerDesc()
    if isNull(self.playerDesc) then
        return self.defaultPlayerDesc
    end
    for playerId, desc in pairs(self.playerDesc) do
        if playerId ~= self.myPlayerId then
            return desc
        end
    end
    return self.defaultPlayerDesc
end

--- 获取玩家数量
function UIBattlePlayerInfoMgr:GetPlayerNum()
    if isNull(self.playerDesc) then
        return 1
    end
    return table.count(self.playerDesc)
end

return UIBattlePlayerInfoMgr